  saveCredentialManagement(){if(this.injectFailure){this.flowError='凭据变更失败，原版本仍保留。';return}const c=this.credential;const act=this.credentialAction;if(act==='rotate'&&!this.newSecret){this.flowError='请选择新凭据文件或填写新字符串。';return}if(['rotate','restore'].includes(act)){c.version++;c.status=act==='restore'?'已停用':'可用'}if(act==='disable')c.status='已停用';if(act==='enable')c.status='可用';if(act==='delete')c.status='回收站';if(act==='metadata'){c.discoverable=this.credentialPublic;c.expires=this.expiryDraft}if(['rotate','disable','delete','restore'].includes(act))this.grants.filter(g=>g.kind==='凭据使用'&&g.state==='有效'&&g.snapshot?.credential===c.id).forEach(g=>g.state='版本失效');this.newSecret='';this.closeFlow()},
